const { ShopifyClientError, normalizeClientError } = require('../errors');
const { requireWithFallback } = require('../require-package');

const {
  getMenuItems,
  createMenuItem,
  updateMenuItem,
  deleteMenuItem,
  getPages,
  findBlogByHandle
} = requireWithFallback(
  require,
  '../../../../../lib/objects/menus',
  '../../../../cli/lib/objects/menus'
);

function wrap(operation, fn) {
  return async (...args) => {
    try {
      return await fn(...args);
    } catch (error) {
      throw normalizeClientError(error, `${operation} failed`);
    }
  };
}

function createMenusClient({ store }) {
  if (!store) {
    throw new ShopifyClientError('Menus client requires a bound store', {
      code: 'MISSING_STORE'
    });
  }

  return {
    listAll: wrap('Menu list', () => getMenuItems(store)),
    create: wrap('Menu create', (menuData) => createMenuItem(store, menuData)),
    update: wrap('Menu update', (menuId, menuData) => updateMenuItem(store, menuId, menuData)),
    delete: wrap('Menu delete', (menuId) => deleteMenuItem(store, menuId)),
    listPages: wrap('Page list', () => getPages(store)),
    findBlogByHandle: wrap('Blog lookup', (handle) => findBlogByHandle(store, handle))
  };
}

module.exports = {
  createMenusClient
};
